/* KPI stat box - pill style */
.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-card {

    padding: 1.25rem 1.35rem;

    height: 100%;

    border-radius: 10px;

    border: none;

    box-shadow: 0 4px 12px rgba(0, 45, 94, 0.06);

}



.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-card:hover {

    transform: none;

    box-shadow: 0 6px 16px rgba(0, 45, 94, 0.1);

}



.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-inner {

    gap: 0.75rem;

}



.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-main {

    min-width: 0;

    flex: 1;

}



.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-head {

    display: flex;

    align-items: center;

    gap: 0.4rem;

    margin-bottom: 0.65rem;

}



.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-head-icon {

    font-size: 1rem;

    color: #002d5e;

    flex-shrink: 0;

    line-height: 1;

}



.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-title {

    font-size: 0.72rem;

    font-weight: 700;

    color: #002d5e;

    text-transform: uppercase;

    letter-spacing: 0.02em;

    line-height: 1.3;

}



.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-pill {

    display: inline-block;

    background-color: #e8efff;

    border-radius: 50px;

    padding: 0.35rem 1rem;

    min-width: 56px;

    text-align: center;

}



.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-card .sch-dash-kpi-value {

    font-size: 1.1rem;

    font-weight: 700;

    color: #002d5e;

    line-height: 1.2;

}



.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-deco {

    width: 44px;

    height: 44px;

    border: 1px dashed #3b82f6;

    border-radius: 50%;

    display: flex;

    align-items: center;

    justify-content: center;

    flex-shrink: 0;

    color: #002d5e;

    font-size: 1.05rem;

}



.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-teal .ssd-dash-kpi-head-icon,

.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-teal .ssd-dash-kpi-title,

.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-teal .sch-dash-kpi-value {

    color: #0f766e;

}



.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-teal .ssd-dash-kpi-pill {

    background-color: rgba(26, 188, 156, 0.14);

}



.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-teal .ssd-dash-kpi-deco {

    border-color: #1abc9c;

    color: #1abc9c;

}



.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-blue .ssd-dash-kpi-head-icon,

.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-blue .ssd-dash-kpi-title,

.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-blue .sch-dash-kpi-value {

    color: #1d4ed8;

}



.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-blue .ssd-dash-kpi-pill {

    background-color: rgba(52, 152, 219, 0.14);

}



.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-blue .ssd-dash-kpi-deco {

    border-color: #3498db;

    color: #3498db;

}



.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-orange .ssd-dash-kpi-head-icon,

.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-orange .ssd-dash-kpi-title,

.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-orange .sch-dash-kpi-value {

    color: #c2410c;

}



.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-orange .ssd-dash-kpi-pill {

    background-color: rgba(230, 126, 34, 0.14);

}



.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-orange .ssd-dash-kpi-deco {

    border-color: #e67e22;

    color: #e67e22;

}



.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-yellow .ssd-dash-kpi-head-icon,

.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-yellow .ssd-dash-kpi-title,

.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-yellow .sch-dash-kpi-value {

    color: #a16207;

}



.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-yellow .ssd-dash-kpi-pill {

    background-color: rgba(212, 161, 6, 0.16);

}



.page-wrapper .page-content .ssd-dash-root .ssd-dash-kpi-yellow .ssd-dash-kpi-deco {

    border-color: #d4a106;

    color: #d4a106;

}
